@Composable private fun LeadDetails(lead:LeadSummary,back:()->Unit,followUp:()->Unit,checkIn:()->Unit){LazyColumn(Modifier.fillMaxSize().padding(16.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){item{TextButton(back,contentPadding=PaddingValues(0.dp)){Text("← Back")};Text("Lead Details",style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold,color=SalesInk);HorizontalDivider(Modifier.padding(top=8.dp),color=SalesLine)};item{OutlinedCard(Modifier.fillMaxWidth()){Column(Modifier.padding(16.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){Row{Text(lead.title,Modifier.weight(1f),style=MaterialTheme.typography.titleLarge,fontWeight=FontWeight.Bold);StatusChip(stageLabel(lead.stage))};Text(lead.customer?.name?:lead.companyName?:"Prospect",color=SalesInk);Text("Assigned: ${lead.assignedUser.name}",color=SalesMuted);Text("Source: ${lead.source}",color=SalesMuted);Text("${lead.visitCount} check-in / visit${if(lead.visitCount==1)"" else "s"}",color=SalesMuted);lead.estimatedValue?.let{Text("${lead.currencyCode} $it",color=SalesMuted)};lead.updatedAt?.let{Text("Updated ${friendlyLeadDate(it)}",color=SalesMuted);};OutlinedButton(followUp,Modifier.fillMaxWidth()){Text("+ Add Follow-up")};if(lead.canAddCheckIn&&lead.stage !in listOf(LeadStage.WON,LeadStage.LOST))Button(checkIn,Modifier.fillMaxWidth()){Text("+ Add Check-in")}}}}}}
