@Composable private fun PendingPhoneDialog(visit:PendingLeadVisit,busy:Boolean,dismiss:()->Unit,save:(String)->Unit){var phone by remember{mutableStateOf("")};AlertDialog(onDismissRequest=dismiss,title={Text("Add phone")},text={Column(verticalArrangement=Arrangement.spacedBy(8.dp)){Text(visit.customerName?:visit.contactName?:"Pending check-in",fontWeight=FontWeight.Bold);OutlinedTextField(phone,{phone=it},label={Text("Add phone to create Lead")},singleLine=true)}},confirmButton={Button({save(phone.trim())},enabled=!busy&&phone.isNotBlank()){Text(if(busy)"Adding…" else "Add phone")}},dismissButton={TextButton(dismiss){Text("Cancel")}})}
